function maskPII(text, known) {
  let s = String(text ?? '');
  const hits = {};
  const rep = (re, label) => { s = s.replace(re, () => { hits[label] = (hits[label] || 0) + 1; return '[' + label + ']'; }); };
  for (const [v, label] of known) { if (v && v.length >= 2 && s.includes(v)) { hits[label] = (hits[label] || 0) + 1; s = s.split(v).join('[' + label + ']'); } }
  rep(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, 'EMAIL');
  rep(/\b\d(?:[ -]?\d){12,15}\b/g, 'CARD');
  rep(/(?<!\d)\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}(?!\d)/g, 'PHONE');
  rep(/\+\d{1,3}[-\s]?\(?\d{1,4}\)?[-\s]?\d{2,4}[-\s]?\d{3,4}\b/g, 'PHONE');
  rep(/(?<![\d-])〒?\s?\d{3}-\d{4}(?![\d-])/g, 'POSTAL');
  rep(/(?:\+81[-\s]?|\b0)\d{1,4}[-\s]?\d{1,4}[-\s]?\d{3,4}\b/g, 'PHONE');
  rep(/(?<=(?:注文|受付|会員|契約|お客様|order|account|member|contract|customer|reservation)\s?(?:番号|No\.?|ID|number|#)[:：\s#]*)[A-Za-z0-9-]{5,}/gi, 'ID');
  return { text: s, hits };
}

const b = $input.first().json.body ?? $input.first().json;
const message = String(b.message ?? '').trim();
if (!message) throw new Error('message is required');
const name = String(b.name ?? '').trim();
const email = String(b.email ?? '').trim();
const known = [[name, 'NAME'], [email, 'EMAIL'], ...name.split(/[\s　]+/).map(p => [p, 'NAME'])];
const m = maskPII(message, known);
return [{ json: {
  case_id: 'C-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
  received_at: new Date().toISOString(),
  customer_name: name,
  customer_email: email,
  question_raw: message,
  question_masked: m.text,
  pii_hits: m.hits
} }];

// Similarity threshold. 0.75 is only a starting value. Scores depend on the embedding model,
// so tune it with your own data (look at wrong auto-replies and missed matches).
const THRESHOLD = 0.75;
const base = $('Normalize and mask input').first().json;
const hits = $input.all()
  .map(i => i.json)
  .filter(j => j.document)
  .map(j => ({ score: j.score, q: j.document.pageContent, a: j.document.metadata?.answer_masked, case_id: j.document.metadata?.case_id }))
  .sort((x, y) => y.score - x.score);
const top = hits[0];
const refs = hits.filter(h => h.score >= THRESHOLD && h.a).slice(0, 2);
return [{ json: {
  ...base,
  top_score: top ? top.score : 0,
  threshold: THRESHOLD,
  matched: refs.length > 0,
  refs,
  refs_text: refs.map((r, i) => 'Reference ' + (i + 1) + ' (similarity ' + r.score.toFixed(2) + ')\nQ: ' + r.q + '\nA: ' + r.a).join('\n\n')
} }];

const base = $('Check similarity').first().json;
let can = false, reply = '';
try {
  const rawText = $json.content?.[0]?.text ?? $json.text;
  // Claude has no JSON mode, so it may wrap the JSON in a code fence. Strip it before parsing.
  const t = String(rawText ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  const o = JSON.parse(t);
  can = o.can_answer === true;
  reply = String(o.reply ?? '').trim();
} catch (e) { can = false; }
// Never auto-send an empty reply or one that still contains a placeholder
if (!reply || /\[[A-Z_]+\]/.test(reply)) can = false;
const greeting = (base.customer_name ? 'Dear ' + base.customer_name + ',\n\n' : '') + 'Thank you for contacting us.\n\n';
const footer = '\n\nThis is an automated reply based on past answers. If it does not solve your problem, just reply to this message and a staff member will help.';
return [{ json: { ...base, can_answer: can, auto_answer: can ? greeting + reply + footer : '' } }];

const d = $('Validate the draft').first().json;
return [{ json: {
  status: 'auto_answered',
  case_id: d.case_id,
  answer: d.auto_answer,
  match_score: d.top_score,
  matched_questions: d.refs.map(r => r.q)
} }];

const d = $('Check similarity').first().json;
return [{ json: {
  status: 'pending',
  case_id: d.case_id,
  message: 'A staff member will review your inquiry and reply.',
  match_score: d.top_score
} }];

