const row = $input.first().json;
const req = $('Webhook: Staff answer').first().json.body ?? {};
const answer = String(req.answer ?? '').trim();
let reject = '';
if (!row.case_id) reject = 'No case matches this case_id';
else if (row.status !== 'pending') reject = 'This case is not waiting for staff (status=' + row.status + ')';
else if (!answer) reject = 'answer is required';
if (reject) return [{ json: { ok: false, reject_reason: reject, case_id: req.case_id ?? null } }];

const name = row.customer_name || '';
const email = row.customer_email || '';
const known = [[name, 'NAME'], [email, 'EMAIL'], ...name.split(/[\s　]+/).map(p => [p, 'NAME'])];
const q = maskPII(row.question_raw, known);
const a = maskPII(answer, known);
return [{ json: {
  ok: true,
  case_id: row.case_id,
  staff: String(req.staff ?? ''),
  learn: req.learn !== false,
  answer_raw: answer,
  question_rx: q.text,
  answer_rx: a.text,
  pii_hits: { question: q.hits, answer: a.hits }
} }];

