const base = $('Validate and mask with regex').first().json;
let q = '', a = '', reason = '';
try {
  const rawText = $json.content?.[0]?.text ?? $json.text;
  // Claude has no JSON mode, so it may wrap the JSON in a code fence. Strip it before parsing.
  const t = String(rawText ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  const o = JSON.parse(t);
  q = String(o.question ?? '');
  a = String(o.answer ?? '');
} catch (e) { reason = 'The AI output could not be read as JSON'; }
if (!reason) {
  if (!q.trim() || !a.trim()) reason = 'The AI output is empty';
  else if (q.length < base.question_rx.length * 0.5 || a.length < base.answer_rx.length * 0.5) reason = 'The AI output is much shorter than the input (possible summary or loss)';
  else {
    const r = maskPII(q + '\n' + a, []);
    const left = Object.keys(r.hits);
    if (left.length) reason = 'Personal data patterns remain after masking: ' + left.join(',');
  }
}
if (!reason && !base.learn) reason = 'Staff chose not to learn this answer';
return [{ json: { ...base, learn_ok: !reason, mask_note: reason, question_masked: q, answer_masked: a } }];

const d = $('Check the masking result').first().json;
return [{ json: {
  status: 'learned',
  case_id: d.case_id,
  masked_question: d.question_masked,
  masked_answer: d.answer_masked,
  pii_hits: d.pii_hits
} }];
